    for _ in range(n):
        x, y = map(float, sys.stdin.readline().split())
        points.append((x, y))

    hull = convex_hull(points)
    m = len(hull)
    if m < 2:
        perimeter = 0.0
    elif m == 2:
        a, b = hull[0], hull[1]
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        perimeter = math.hypot(dx, dy)
    else:
        perimeter = 0.0
        for i in range(m):
            a = hull[i]
            b = hull[(i + 1) % m]
            dx = a[0] - b[0]
            dy = a[1] - b[1]
            perimeter += math.hypot(dx, dy)

    print("{0:.3f}".format(perimeter))

